"""Regenerate the binary test fixtures from the anonymised XML sources in ``src/``.

Usage:  python tests/fixtures/build_fixtures.py

All addresses use example domains (RFC 2606) and documentation IP ranges (RFC 5737 /
RFC 3849) where possible; well-known public infrastructure IPs (Microsoft, Google) are
kept so the reporter-specific shape stays realistic. Output is deterministic.
"""

from __future__ import annotations

import base64
import gzip
import io
import zipfile
from email.mime.application import MIMEApplication
from email.mime.multipart import MIMEMultipart
from email.mime.text import MIMEText
from pathlib import Path

HERE = Path(__file__).resolve().parent
SRC = HERE / "src"
RUA = HERE / "rua"
RUF = HERE / "ruf"
BROKEN = HERE / "broken"
FIXED_DATE = (2025, 11, 25, 0, 0, 0)


def src(name: str) -> bytes:
    return (SRC / name).read_bytes()


def gz(data: bytes) -> bytes:
    return gzip.compress(data, mtime=0)


def make_zip(files: dict[str, bytes]) -> bytes:
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as zf:
        for name, data in files.items():
            zf.writestr(zipfile.ZipInfo(name, FIXED_DATE), data, compress_type=zipfile.ZIP_DEFLATED)
    return buf.getvalue()


def report_mail(sender: str, subject: str, attachment: bytes, filename: str, ctype: str, msgid: str,
                body: str = "This is an aggregate report.") -> bytes:
    msg = MIMEMultipart(boundary="==fixture-boundary==")
    msg["From"] = sender
    msg["To"] = "dmarc-reports@example.com"
    msg["Subject"] = subject
    msg["Date"] = "Tue, 25 Nov 2025 06:12:00 +0000"
    msg["Message-ID"] = msgid
    msg.attach(MIMEText(body, "plain"))
    maintype, subtype = ctype.split("/")
    part = MIMEApplication(attachment, _subtype=subtype)
    if maintype != "application":
        part.replace_header("Content-Type", ctype)
    part.add_header("Content-Disposition", "attachment", filename=filename)
    msg.attach(part)
    return msg.as_bytes()


def write(path: Path, data: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(data)
    print(f"wrote {path.relative_to(HERE)} ({len(data)} bytes)")


def build_rua() -> None:
    write(RUA / "google.eml", report_mail(
        "noreply-dmarc-support@google.com",
        "Report domain: example.com Submitter: google.com Report-ID: 13190401177745345981",
        make_zip({"google.com!example.com!1763942400!1764028799.xml": src("google.xml")}),
        "google.com!example.com!1763942400!1764028799.zip", "application/zip",
        "<13190401177745345981@google.com>"))
    write(RUA / "microsoft.eml", report_mail(
        "DMARC Aggregate Report <dmarcreport@microsoft.com>",
        "Report Domain: example.com Submitter: enterprise.protection.outlook.com Report-ID: a1b2c3d4e5f60718293a4b5c6d7e8f90",
        gz(src("microsoft.xml")),
        "enterprise.protection.outlook.com!example.com!1763942400!1764028800.xml.gz", "application/gzip",
        "<a1b2c3d4e5f6@microsoft.com>"))
    write(RUA / "yahoo.eml", report_mail(
        "dmarchelp@yahooinc.com", "Report Domain: example.com Submitter: Yahoo Report-ID: <1764000000.592341>",
        gz(src("yahoo.xml")), "yahoo.com!example.com!1763942400!1764028799.xml.gz", "application/octet-stream",
        "<1764000000.592341@yahoo.com>"))
    write(RUA / "mailru.eml", report_mail(
        "dmarc_support@corp.mail.ru", "=?UTF-8?B?UmVwb3J0IERvbWFpbjogZXhhbXBsZS5jb20=?=",
        gz(src("mailru.xml")), "mail.ru!example.com!1763942400!1764028800.xml.gz", "application/x-gzip",
        "<28461832491357283071@mail.ru>"))
    write(RUA / "quirky.eml", report_mail(
        "dmarc@quirky.example", "DMARC report", src("quirky.xml"), "report.xml", "text/xml", "<q-7781@quirky.example>"))
    write(RUA / "dmarcbis.xml.gz", gz(src("dmarcbis.xml")))
    write(RUA / "multi.zip", make_zip({
        "reports/google.xml": src("google.xml"),
        "reports/yahoo.xml": src("yahoo.xml"),
        "README.txt": b"Generated by ExampleMTA",
    }))
    write(RUA / "nested.zip", make_zip({"microsoft.xml.gz": gz(src("microsoft.xml"))}))

    # Inline: XML directly in a text/plain body (some small reporters do this).
    inline = MIMEText("Hello,\n\nPlease find the DMARC report below.\n\n" + src("yahoo.xml").decode() + "\n--\nReporter", "plain")
    inline["From"] = "postmaster@small-isp.example"
    inline["To"] = "dmarc-reports@example.com"
    inline["Subject"] = "DMARC Aggregate Report"
    inline["Message-ID"] = "<inline-1@small-isp.example>"
    write(RUA / "inline.eml", inline.as_bytes())


def build_broken() -> None:
    good = src("google.xml")
    write(BROKEN / "truncated.xml", good[: len(good) // 2])
    write(BROKEN / "corrupt.xml.gz", gz(good)[:40] + b"\x00garbage")
    write(BROKEN / "corrupt.zip", b"PK\x03\x04" + b"\x00" * 30 + b"not really a zip")
    write(BROKEN / "missing_report_id.xml", good.replace(b"<report_id>13190401177745345981</report_id>", b""))
    write(BROKEN / "wrong_root.xml", b"<?xml version='1.0'?><html><body>Not a report</body></html>")
    write(BROKEN / "xxe.xml", b"""<?xml version="1.0"?>
<!DOCTYPE feedback [ <!ENTITY xxe SYSTEM "file:///etc/passwd"> ]>
<feedback><report_metadata><org_name>&xxe;</org_name></report_metadata></feedback>""")
    write(BROKEN / "billion_laughs.xml", b"""<?xml version="1.0"?>
<!DOCTYPE lolz [
 <!ENTITY lol "lol">
 <!ENTITY lol2 "&lol;&lol;&lol;&lol;&lol;&lol;&lol;&lol;&lol;&lol;">
 <!ENTITY lol3 "&lol2;&lol2;&lol2;&lol2;&lol2;&lol2;&lol2;&lol2;&lol2;&lol2;">
 <!ENTITY lol4 "&lol3;&lol3;&lol3;&lol3;&lol3;&lol3;&lol3;&lol3;&lol3;&lol3;">
]>
<feedback><report_metadata><org_name>&lol4;</org_name></report_metadata></feedback>""")
    write(BROKEN / "pdf_named_zip.eml", report_mail(
        "someone@example.org", "Report", b"%PDF-1.4 fake", "report.zip", "application/zip", "<pdf@example.org>"))
    plain = MIMEText("Just a normal message, no report here.", "plain")
    plain["From"] = "colleague@example.com"
    plain["Subject"] = "Lunch?"
    plain["Message-ID"] = "<lunch@example.com>"
    write(BROKEN / "no_report.eml", plain.as_bytes())

    # One valid and one broken attachment in the same message.
    msg = MIMEMultipart(boundary="==mixed-boundary==")
    msg["From"] = "dmarc@mixed.example"
    msg["Subject"] = "Two reports"
    msg["Message-ID"] = "<mixed@mixed.example>"
    for data, name in ((gz(src("dmarcbis.xml")), "good.xml.gz"), (good[:200], "bad.xml")):
        p = MIMEApplication(data, _subtype="octet-stream")
        p.add_header("Content-Disposition", "attachment", filename=name)
        msg.attach(p)
    write(BROKEN / "mixed.eml", msg.as_bytes())


ORIGINAL = b"""Received: from unknown (HELO spoofer.example) (203.0.113.66)
  by mx.receiver.example with SMTP; Mon, 24 Nov 2025 10:15:02 +0000
From: "Finance" <finance@example.com>
To: victim@receiver.example
Subject: Urgent invoice
Date: Mon, 24 Nov 2025 10:15:00 +0000
Message-ID: <spoof-123@spoofer.example>
MIME-Version: 1.0
Content-Type: text/plain; charset=utf-8

Please pay the attached invoice to IBAN XX00 0000 0000 00.
"""

FEEDBACK = b"""Feedback-Type: auth-failure
User-Agent: ReceiverMTA/2.1
Version: 1
Original-Mail-From: <bounce@spoofer.example>
Original-Rcpt-To: <victim@receiver.example>
Arrival-Date: Mon, 24 Nov 2025 10:15:02 +0000
Source-IP: 203.0.113.66
Reported-Domain: example.com
Authentication-Results: mx.receiver.example; dmarc=fail (p=none) header.from=example.com; spf=fail smtp.mailfrom=spoofer.example; dkim=none
Auth-Failure: dmarc
Delivery-Result: delivered
Identity-Alignment: none
"""


def arf(feedback_part: bytes, original_part: bytes, msgid: str) -> bytes:
    return b"""From: DMARC Failure Reports <ruf-reports@receiver.example>
To: dmarc-reports@example.com
Subject: FW: Urgent invoice
Date: Mon, 24 Nov 2025 10:20:00 +0000
Message-ID: """ + msgid.encode() + b"""
MIME-Version: 1.0
Content-Type: multipart/report; report-type=feedback-report; boundary="arf-boundary"

--arf-boundary
Content-Type: text/plain; charset=us-ascii

This is an authentication failure report for an email message received from 203.0.113.66.

--arf-boundary
""" + feedback_part + b"""
--arf-boundary
""" + original_part + b"""
--arf-boundary--
"""


PHISHING = b"""Received: from mx.receiver.example (mx.receiver.example [198.51.100.5])
  by mailstore.receiver.example with LMTP; Mon, 24 Nov 2025 11:02:05 +0000
Received: from mail.bulk-sender.example (mail.bulk-sender.example [203.0.113.66])
  by mx.receiver.example (Postfix) with ESMTPS id 4XyZ for <j.jansen@receiver.example>; Mon, 24 Nov 2025 11:02:03 +0000
Received: from [10.1.2.3] (helo=workstation) by mail.bulk-sender.example with esmtpa; Mon, 24 Nov 2025 11:02:00 +0000
Authentication-Results: mx.receiver.example; dkim=pass header.d=bulk-sender.example header.s=k1; spf=fail smtp.mailfrom=bulk-sender.example; dmarc=fail (p=none) header.from=example.com
DKIM-Signature: v=1; a=rsa-sha256; c=relaxed/relaxed; d=bulk-sender.example; s=k1; h=from:to:subject; bh=abc=; b=def=
From: "finance@example.com" <noreply@example.com>
Reply-To: payments@collect-invoices.example
To: "Jan Jansen" <j.jansen@receiver.example>
Subject: Outstanding invoice 2025-1187
Date: Mon, 24 Nov 2025 11:01:59 +0000
Message-ID: <a1b2c3@bulk-sender.example>
X-Mailer: MassMailer Pro 7.2
MIME-Version: 1.0
Content-Type: multipart/mixed; boundary="outer"

--outer
Content-Type: multipart/alternative; boundary="alt"

--alt
Content-Type: text/plain; charset=utf-8

Dear customer, please pay invoice 2025-1187 via https://pay.collect-invoices.example/inv?id=1187
--alt
Content-Type: text/html; charset=utf-8

<html><body><p>Dear customer,</p><p>Please <a href="https://pay.collect-invoices.example/inv?id=1187">pay invoice 2025-1187</a>.
Questions? <a href="https://www.example.com/contact">Contact us</a> or <a href="mailto:x@example.com">mail</a>.</p>
<script>alert(1)</script></body></html>
--alt--

--outer
Content-Type: application/pdf; name="invoice-2025-1187.pdf"
Content-Disposition: attachment; filename="invoice-2025-1187.pdf"
Content-Transfer-Encoding: base64

JVBERi0xLjQKJWZha2UgcGRmCg==
--outer--
"""


def build_ruf() -> None:
    write(RUF / "arf_full.eml", arf(
        b"Content-Type: message/feedback-report\n\n" + FEEDBACK,
        b"Content-Type: message/rfc822\nContent-Disposition: inline\n\n" + ORIGINAL,
        "<ruf-1@receiver.example>"))
    headers_only = ORIGINAL.split(b"\n\n", 1)[0] + b"\n"
    write(RUF / "arf_headers_only.eml", arf(
        b"Content-Type: message/feedback-report\n\n" + FEEDBACK.replace(b"Delivery-Result: delivered\n", b""),
        b"Content-Type: text/rfc822-headers\n\n" + headers_only,
        "<ruf-2@receiver.example>"))
    b64 = base64.encodebytes(FEEDBACK)
    write(RUF / "arf_base64.eml", arf(
        b"Content-Type: message/feedback-report\nContent-Transfer-Encoding: base64\n\n" + b64,
        b"Content-Type: text/rfc822-headers\n\n" + headers_only,
        "<ruf-3@receiver.example>"))
    write(RUF / "arf_phishing.eml", arf(
        b"Content-Type: message/feedback-report\n\n" + FEEDBACK
        .replace(b"Arrival-Date: Mon, 24 Nov 2025 10:15:02", b"Arrival-Date: Mon, 24 Nov 2025 11:02:03")
        .replace(b"spf=fail smtp.mailfrom=spoofer.example; dkim=none", b"spf=fail smtp.mailfrom=bulk-sender.example; dkim=pass header.d=bulk-sender.example")
        .replace(b"<bounce@spoofer.example>", b"<bounce@bulk-sender.example>")
        .replace(b"<victim@receiver.example>", b"<j.jansen@receiver.example>"),
        b"Content-Type: message/rfc822\n\n" + PHISHING,
        "<ruf-5@receiver.example>"))
    write(BROKEN / "arf_no_feedback_type.eml", arf(
        b"Content-Type: message/feedback-report\n\n" + FEEDBACK.replace(b"Feedback-Type: auth-failure\n", b""),
        b"Content-Type: text/rfc822-headers\n\n" + headers_only,
        "<ruf-4@receiver.example>"))


if __name__ == "__main__":
    build_rua()
    build_broken()
    build_ruf()
